package com.geno1024.ai.worm.android.ui

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp
import com.geno1024.ai.worm.android.site.Source

/**
 * Monochrome 24×24 site glyphs for the source drawer. Paths come from Simple Icons
 * (CC0 1.0), are embedded verbatim and are tinted by Material's `Icon` like any other
 * icon, so the set keeps one visual weight in every theme. No runtime downloads.
 */
object SourceIcons {
    fun of(source: Source): ImageVector = when (source) {
        Source.QZONE, Source.QZONE_ALBUM -> QZONE
        Source.WEIBO -> WEIBO
        Source.FACEBOOK -> FACEBOOK
        Source.ZHIHU -> ZHIHU
    }

    private fun icon(name: String, path: String): ImageVector = ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
    ).apply {
        addPath(pathData = PathParser().parsePathString(path).toNodes(), fill = SolidColor(Color.Black))
    }.build()

